function solve(o){
  var v=o.v,i=o.i,r=o.r,p=o.p;
  var known=0;[v,i,r,p].forEach(function(x){if(typeof x==='number'&&isFinite(x))known++;});
  if(known<2)return {error:'至少需要提供两个量'};
  if(v!=null&&i!=null){r=v/i;p=v*i;}
  else if(v!=null&&r!=null){if(r===0)return {error:'电阻不能为 0'};i=v/r;p=v*v/r;}
  else if(i!=null&&r!=null){v=i*r;p=i*i*r;}
  else if(v!=null&&p!=null){if(v===0)return {error:'电压不能为 0'};i=p/v;r=v/i;}
  else if(i!=null&&p!=null){if(i===0)return {error:'电流不能为 0'};v=p/i;r=v/i;}
  else if(r!=null&&p!=null){if(r===0)return {error:'电阻不能为 0'};i=Math.sqrt(p/r);v=i*r;}
  else return {error:'需要提供可求解的组合'};
  return {v:v,i:i,r:r,p:p};
}
function series(arr){var s=0;for(var k=0;k<arr.length;k++)s+=arr[k];return s;}
function parallel(arr){var inv=0;for(var k=0;k<arr.length;k++){if(arr[k]===0)return Infinity;inv+=1/arr[k];}return inv?1/inv:Infinity;}
